    "declic_frequence": "adhina (autoriser, permettre, racine أ-ذ-ن — d'où adhān, l'appel à la prière) marque au v.39 un tournant historique : udhina lilladhīna yuqātalūna bi-annahum ẓulimū — « autorisation est donnée à ceux qui sont attaqués, parce qu'ils ont été lésés ». Premier verset permettant la défense armée après des années de patience mecquoise. Le combat n'est pas ouvert par agression mais par autorisation défensive, strictement liée à l'injustice subie (ẓulimū) : on ne se défend que parce qu'on a d'abord été frappé."
